from threetears.evals import Eval

from points import basket_lines, points_for

def award(case):
    """The points the basket earns the member."""
    return {"points": points_for(basket_lines(case), case["tier"]).total}


def matches_old_till(case, out):
    """The basket earns the points the old till put on the card."""
    return out["points"] == case["points_awarded"]

baskets = Eval("data/till_export.jsonl", runner=award, grader=[matches_old_till], k=1)
